import{_ as s,o as i,c as a,a0 as o}from"./chunks/framework.BLL-IG04.js";const k=JSON.parse('{"title":"How-to: multi-repo checking","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/multi-repo.md","filePath":"how-to/multi-repo.md"}'),t={name:"how-to/multi-repo.md"};function r(n,e,l,h,c,p){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="how-to-multi-repo-checking" tabindex="-1">How-to: multi-repo checking <a class="header-anchor" href="#how-to-multi-repo-checking" aria-label="Permalink to &quot;How-to: multi-repo checking&quot;">​</a></h1><p>Docs in one repo make claims about sibling repos — moved crates, <code>see ../&lt;repo&gt;</code>, cross-repo commands. mimus verifies those claims where it can reach reality.</p><h2 id="per-repo-config" tabindex="-1">Per-repo config <a class="header-anchor" href="#per-repo-config" aria-label="Permalink to &quot;Per-repo config&quot;">​</a></h2><p>Each repo keeps its own <code>mimus.toml</code> and <code>rules/</code> — conventions are repo-scoped (a rule that is right for <code>platform</code> is noise in <code>lsp</code>). Run <code>mimus check</code> per repo, or script the sweep:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> r </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/GitHub/handl-lang/*/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">do</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/mimus.toml&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ] &amp;&amp; (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mimus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">done</span></span></code></pre></div><h2 id="cross-repo-claims-today" tabindex="-1">Cross-repo claims today <a class="header-anchor" href="#cross-repo-claims-today" aria-label="Permalink to &quot;Cross-repo claims today&quot;">​</a></h2><ul><li><strong>Paths</strong> are resolved relative to the repo root — a ../sibling/crate claim in docs verifies if the sibling exists.</li><li><strong>Commands</strong> check PATH, which is host-global — a doc telling users to run <code>hnl</code> is verified wherever <code>hnl</code> is installed.</li><li><strong>Symbols</strong> need a kuda index per repo; the <code>symbol</code> checker reads <code>.kuda/index.sqlite</code> of the <em>current</em> root. Cross-repo symbol resolution rides on kuda workspace mode.</li></ul><h2 id="rules-at-scale" tabindex="-1">Rules at scale <a class="header-anchor" href="#rules-at-scale" aria-label="Permalink to &quot;Rules at scale&quot;">​</a></h2><p>Keep org-wide conventions in one place and symlink or vendor them per repo — a shared rules/org/ directory fetched in CI works today; first-class rule inheritance is a backlog item.</p><h2 id="where-it-goes-next" tabindex="-1">Where it goes next <a class="header-anchor" href="#where-it-goes-next" aria-label="Permalink to &quot;Where it goes next&quot;">​</a></h2><p><code>kuda sync --workspace</code> produces per-root indexes across the sibling set; the <code>symbol</code> checker then resolves claims like <code> `hnl` lives in the cli repo</code> against the merged stores — the &quot;which repo owns this&quot; question becomes verifiable.</p>',11)])])}const m=s(t,[["render",r]]);export{k as __pageData,m as default};
